  constructor(private http: HttpClient) {}

  copyToClipboard(link: string | undefined): void {
    if (link) {
      navigator.clipboard.writeText(link).then(
        () => alert('Link copied to clipboard!'),
        (err) => console.error('Could not copy text: ', err)
      );
    } else {
      alert('No link available to copy.');
    }
  }

  toggleHealthCheck(card: AppCard) {
    card.isRunning = true;
    const apiUrl = card.healthCheckUrl;

    this.http.post<any>(apiUrl, card.payload).subscribe(
      (response) => {
        card.status = (response.success === true) ? 'Healthy' : 'Unhealthy';
        card.isRunning = false;
      },
      (error) => {
        card.status = 'Unhealthy';
        card.isRunning = false;
      }
    );
  }

  runAllChecks() {
    this.cards.forEach((card) => {
      card.isRunning = true;
      const apiUrl = card.healthCheckUrl;

      this.http.post<any>(apiUrl, card.payload).subscribe(
        (response) => {
          card.status = (response.success === true) ? 'Healthy' : 'Unhealthy';
          card.isRunning = false;
        },
        (error) => {
          card.status = 'Unhealthy';
          card.isRunning = false;
        }
      );
    });
  }
